class MapInfoImpl {
    id;
    title;
    locked;
    starred;
    lockedMsg;
    creatorFullName;
    constructor(id, title, creatorFullName, locked, lockedMsg) {
        this.id = id;
        this.title = title;
        this.locked = locked;
        this.lockedMsg = lockedMsg;
        this.starred = true;
        this.creatorFullName = creatorFullName;
    }
    getCreatorFullName() {
        return this.creatorFullName;
    }
    isStarred() {
        return Promise.resolve(this.starred);
    }
    updateStarred(value) {
        this.starred = value;
        return Promise.resolve();
    }
    getTitle() {
        return this.title;
    }
    getLockedMsg() {
        return this.lockedMsg;
    }
    updateTitle(title) {
        this.title = title;
        return Promise.resolve();
    }
    isLocked() {
        return this.locked;
    }
    getLockedMessage() {
        return 'Map Is Locked !';
    }
    getZoom() {
        return 0.8;
    }
    getId() {
        return this.id;
    }
}
export default MapInfoImpl;
